// Auto-transition: in_review → code_review (MC API handles assignee=tester + dual review setup)
// Replaces old child-issue creation pattern (retired with review-gate.py)
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const MC_API = 'http://localhost:3000/api/issues';

const staticData = $getWorkflowStaticData('global');
if (!staticData.transitioned) staticData.transitioned = {};
const now = Date.now();
// Prune old entries
for (const [id, ts] of Object.entries(staticData.transitioned)) {
  if (now - ts > 7 * 24 * 60 * 60 * 1000) delete staticData.transitioned[id];
}

// Find issues in in_review not yet transitioned
const twoMinAgo = new Date(now - 2.5 * 60 * 1000).toISOString();
const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.in_review&updated_at=gt.' + twoMinAgo + '&select=id,task_key,title,assignee,implementation_notes,commit_sha,regression_test',
  headers: h
});

if (!issues.length) return [{ json: { processed: 0 } }];

const results = [];
for (const issue of issues) {
  if (staticData.transitioned[issue.id]) continue;

  try {
    const body = {
      id: issue.id,
      status: 'code_review',
      transitioned_by: 'n8n-tester-trigger',
      implementation_notes: issue.implementation_notes || 'Auto-transitioned from in_review',
      commit_sha: issue.commit_sha || null,
      regression_test: issue.regression_test || null,
    };
    await helpers.httpRequest({
      method: 'PATCH',
      url: MC_API,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    staticData.transitioned[issue.id] = now;
    results.push({ key: issue.task_key, action: 'transitioned to code_review' });
  } catch(e) {
    results.push({ key: issue.task_key, action: 'error: ' + e.message });
  }
}

return [{ json: { processed: results.length, results } }];
